export const COLS = 10
export const ROWS = 16

export const TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L']

// Rotation centre is (1.5, 1.5) in a 4x4 box, which keeps every
// rotation on integer cells and gives the pieces a familiar feel.
export const BASE_SHAPES = {
  I: [[0, 1], [1, 1], [2, 1], [3, 1]],
  O: [[1, 1], [2, 1], [1, 2], [2, 2]],
  T: [[1, 2], [0, 1], [1, 1], [2, 1]],
  S: [[1, 2], [2, 2], [0, 1], [1, 1]],
  Z: [[0, 2], [1, 2], [1, 1], [2, 1]],
  J: [[0, 2], [0, 1], [1, 1], [2, 1]],
  L: [[2, 2], [0, 1], [1, 1], [2, 1]]
}

function rotateCW(cells) {
  return cells.map(([x, y]) => [y, 3 - x])
}

export const SHAPES = {}
for (const type of TYPES) {
  const rotations = [BASE_SHAPES[type]]
  for (let i = 1; i < 4; i++) {
    if (type === 'O') rotations.push(rotations[0])
    else rotations.push(rotateCW(rotations[i - 1]))
  }
  SHAPES[type] = rotations
}

export function createBag(random = Math.random) {
  const bag = TYPES.slice()
  for (let i = bag.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[bag[i], bag[j]] = [bag[j], bag[i]]
  }
  return bag
}

export function emptyBoard() {
  return Array.from({ length: ROWS }, () => Array(COLS).fill(null))
}

export function cellsFor(type, rot) {
  return SHAPES[type][((rot % 4) + 4) % 4]
}

export function collides(board, cells, x, y) {
  for (const [cx, cy] of cells) {
    const bx = x + cx
    const by = y + cy
    if (bx < 0 || bx >= COLS || by < 0) return true
    if (by >= ROWS) continue
    if (board[by][bx]) return true
  }
  return false
}

export function landingY(board, cells, x, y) {
  let ly = y
  while (!collides(board, cells, x, ly - 1)) ly--
  return ly
}

const KICKS = [
  [0, 0], [-1, 0], [1, 0], [-2, 0], [2, 0], [0, -1], [0, 1], [-1, -1], [1, -1]
]

export function tryRotate(board, piece, dir) {
  const nextRot = ((piece.rot + dir) % 4 + 4) % 4
  const cells = cellsFor(piece.type, nextRot)
  for (const [dx, dy] of KICKS) {
    if (!collides(board, cells, piece.x + dx, piece.y + dy)) {
      return { ...piece, rot: nextRot, x: piece.x + dx, y: piece.y + dy, cells }
    }
  }
  return null
}

export function fullRows(board) {
  const rows = []
  for (let y = 0; y < ROWS; y++) {
    if (board[y].every(Boolean)) rows.push(y)
  }
  return rows
}

export function clearRows(board, rows) {
  const remove = new Set(rows)
  const kept = board.filter((_, y) => !remove.has(y))
  while (kept.length < ROWS) kept.push(Array(COLS).fill(null))
  return kept
}

export const HOUSE_VOXEL = 0.58
export const HOUSE_LINES = 12

/**
 * The cottage blueprint. Coordinates are voxel cells, centred on x/z with
 * y = 0 sitting on the island. The order of this array is the build order:
 * foundation → porch → walls (bottom to top) → roof → chimney → lanterns.
 */
export function createHouseVoxels() {
  const voxels = []
  const seen = new Set()

  function add(x, y, z, mat, stage) {
    const key = `${x},${y},${z}`
    if (seen.has(key)) return
    seen.add(key)
    voxels.push({ x, y, z, mat, stage })
  }

  // Foundation slab.
  for (let z = -3; z <= 3; z++) {
    for (let x = -4; x <= 4; x++) {
      const alt = (x * 7 + z * 11 + 100) % 13 === 0
      add(x, 0, z, alt ? 'foundationAlt' : 'foundation', 'Foundation')
    }
  }

  // Front step + two porch lantern posts.
  for (let x = -1; x <= 1; x++) add(x, 0, 4, 'porch', 'Foundation')
  add(-2, 0, 4, 'frame', 'Foundation')
  add(2, 0, 4, 'frame', 'Foundation')

  // Walls.
  for (let y = 1; y <= 4; y++) {
    for (let z = -3; z <= 3; z++) {
      for (let x = -4; x <= 4; x++) {
        const edge = Math.abs(x) === 4 || Math.abs(z) === 3
        if (!edge) continue
        const corner = Math.abs(x) === 4 && Math.abs(z) === 3
        const door = z === 3 && x === 0 && y <= 2
        const window =
          y === 2 &&
          ((z === 3 && (x === -2 || x === 2)) ||
            (z === -3 && (x === -2 || x === 0 || x === 2)) ||
            (Math.abs(x) === 4 && Math.abs(z) === 1))

        let mat = 'wall'
        if (corner) mat = 'frame'
        else if (y === 4) mat = 'trim'
        if (door) mat = 'door'
        if (window) mat = 'glass'
        add(x, y, z, mat, y < 3 ? 'Walls' : 'Frame')
      }
    }
  }

  // Gabled roof: full layers that step in toward the ridge.
  for (let y = 5; y <= 8; y++) {
    const inset = y - 5
    for (let z = -3 + inset; z <= 3 - inset; z++) {
      for (let x = -4; x <= 4; x++) {
        const chimneyHole = x >= 2 && x <= 3 && z >= -2 && z <= -1
        if (chimneyHole) continue
        add(x, y, z, 'roof', 'Roof')
      }
    }
  }

  // Chimney, threaded through the roof.
  for (let y = 5; y <= 9; y++) {
    for (let z = -2; z <= -1; z++) {
      for (let x = 2; x <= 3; x++) {
        add(x, y, z, 'chimney', 'Chimney')
      }
    }
  }

  // Lanterns go on at the very end.
  add(-2, 1, 4, 'lantern', 'Finishing')
  add(2, 1, 4, 'lantern', 'Finishing')

  return voxels
}

export const STAGE_ORDER = ['Foundation', 'Walls', 'Frame', 'Roof', 'Chimney', 'Finishing']

