import * as THREE from '../vendor/three.module.js'
import { configureTextures, createMaterials } from './textures.js'
import { COLS, ROWS } from './tetris.js'
import { HOUSE_VOXEL } from './house.js'

export const CELL = 0.7
export const BASE_Y = 0.9

const boxGeo = new THREE.BoxGeometry(1, 1, 1)
const rand = (seed) => {
  let a = seed >>> 0
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function tiled(material, rx, ry) {
  const m = material.clone()
  if (m.map) {
    m.map = m.map.clone()
    m.map.wrapS = m.map.wrapT = THREE.RepeatWrapping
    m.map.repeat.set(rx, ry)
    m.map.needsUpdate = true
  }
  return m
}

function addBox(parent, w, h, d, material, x, y, z, cast = true, receive = true) {
  const mesh = new THREE.Mesh(boxGeo, material)
  mesh.scale.set(w, h, d)
  mesh.position.set(x, y, z)
  mesh.castShadow = cast
  mesh.receiveShadow = receive
  parent.add(mesh)
  return mesh
}

function makePuffTexture() {
  const c = document.createElement('canvas')
  c.width = c.height = 64
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(32, 32, 1, 32, 32, 31)
  g.addColorStop(0, 'rgba(255,255,255,1)')
  g.addColorStop(0.4, 'rgba(255,255,255,.65)')
  g.addColorStop(1, 'rgba(255,255,255,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 64, 64)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function addFlowers(group, M, random, count, radiusX, radiusZ, centerZ = 0) {
  const plane = new THREE.PlaneGeometry(0.42, 0.42)
  const colors = [M.flower.red, M.flower.yellow, M.flower.white]
  for (let i = 0; i < count; i++) {
    const x = (random() * 2 - 1) * radiusX
    const z = (random() * 2 - 1) * radiusZ + centerZ
    if (Math.abs(x) < 1.2 && Math.abs(z) < 2.4) continue
    const mat = colors[(random() * colors.length) | 0]
    const holder = new THREE.Group()
    holder.position.set(x, 0.03, z)
    const scale = 0.7 + random() * 0.65
    for (let k = 0; k < 2; k++) {
      const mesh = new THREE.Mesh(plane, mat)
      mesh.position.y = 0.2 * scale
      mesh.scale.setScalar(scale)
      mesh.rotation.y = k * Math.PI / 2 + random() * 0.4
      mesh.castShadow = false
      holder.add(mesh)
    }
    group.add(holder)
  }
}

function addTree(group, M, x, z, scale, seed) {
  const random = rand(seed)
  const tree = new THREE.Group()
  tree.position.set(x, 0, z)
  tree.scale.setScalar(scale)
  const trunkH = 4 + ((random() * 2) | 0)
  for (let i = 0; i < trunkH; i++) {
    addBox(tree, 0.42, 0.42, 0.42, M.env.log, 0, 0.21 + i * 0.42, 0)
  }
  const canopyY = trunkH * 0.42 + 0.1
  for (let ly = -1; ly <= 2; ly++) {
    for (let lx = -1; lx <= 1; lx++) {
      for (let lz = -1; lz <= 1; lz++) {
        if (lx === 0 && lz === 0 && ly < 2) continue
        if (Math.abs(lx) + Math.abs(lz) === 2 && random() > 0.72) continue
        addBox(tree, 0.62, 0.62, 0.62, M.env.leaves,
          lx * 0.58 + (random() - 0.5) * 0.12,
          canopyY + ly * 0.54,
          lz * 0.58 + (random() - 0.5) * 0.12)
      }
    }
  }
  addBox(tree, 0.62, 0.62, 0.62, M.env.leaves, 0, canopyY + 1.22, 0)
  group.add(tree)
  return tree
}

function makeSign(M) {
  const c = document.createElement('canvas')
  c.width = 128
  c.height = 64
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#b78956'
  ctx.fillRect(0, 0, 128, 64)
  ctx.fillStyle = 'rgba(82,50,27,.35)'
  for (let y = 8; y < 64; y += 14) ctx.fillRect(0, y, 128, 2)
  ctx.strokeStyle = '#5d3a20'
  ctx.lineWidth = 5
  ctx.strokeRect(2.5, 2.5, 123, 59)
  ctx.fillStyle = '#2d1c10'
  ctx.font = 'bold 34px "Courier New", monospace'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.fillText('HOME', 64, 34)
  ctx.fillStyle = 'rgba(255,238,196,.35)'
  ctx.fillRect(8, 6, 112, 2)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.magFilter = THREE.NearestFilter
  const mat = new THREE.MeshLambertMaterial({ map: tex, side: THREE.DoubleSide })
  return mat
}

function createIsland({ width, depth, seed, flowers = true, M }) {
  const group = new THREE.Group()
  const random = rand(seed)
  const grassTop = tiled(M.env.grassTop, width / 1.6, depth / 1.6)
  const grassSide = tiled(M.env.grassSide, width / 1.6, 1)
  const dirtTop = tiled(M.env.dirt, width / 2, depth / 2)
  const stone = tiled(M.env.stone, width / 2.2, depth / 2.2)
  const grassBlock = [grassSide, grassSide, grassTop, dirtTop, grassSide, grassSide]

  addBox(group, width, 0.72, depth, grassBlock, 0, -0.36, 0)
  addBox(group, width * 0.98, 0.72, depth * 0.98, dirtTop, 0, -1.03, 0)
  addBox(group, width * 0.93, 0.72, depth * 0.93, dirtTop, 0, -1.7, 0)
  addBox(group, width * 0.82, 0.8, depth * 0.8, stone, 0, -2.4, 0)
  addBox(group, width * 0.62, 0.8, depth * 0.6, stone, 0, -3.1, 0)
  addBox(group, width * 0.38, 0.7, depth * 0.38, stone, 0, -3.72, 0)

  // Chipped, grassy rim made of little blocks.
  const nx = Math.max(4, Math.round(width / 1.05))
  const nz = Math.max(4, Math.round(depth / 1.05))
  const rimCount = nx * 2 + nz * 2
  for (let i = 0; i < rimCount; i++) {
    let x, z
    if (i < nx) { x = -width / 2 + i * (width / (nx - 1)); z = -depth / 2 }
    else if (i < nx * 2) { x = -width / 2 + (i - nx) * (width / (nx - 1)); z = depth / 2 }
    else if (i < nx * 2 + nz) { x = width / 2; z = -depth / 2 + (i - nx * 2) * (depth / (nz - 1)) }
    else { x = -width / 2; z = -depth / 2 + (i - nx * 2 - nz) * (depth / (nz - 1)) }
    if (random() > 0.82) continue
    const h = 0.55 + random() * 0.5
    addBox(group, 0.86, h, 0.86, M.env.grassBlock,
      x + (random() - 0.5) * 0.3, h / 2 - 0.05, z + (random() - 0.5) * 0.3)
  }

  // Hanging rock tips and vines give the chunk a floating look.
  for (let i = 0; i < 7; i++) {
    const s = 0.7 + random() * 1.7
    addBox(group, s, s * 0.8, s, stone,
      (random() - 0.5) * width * 0.6,
      -3.7 - random() * 1.4,
      (random() - 0.5) * depth * 0.6)
  }
  const vineMat = new THREE.MeshLambertMaterial({ color: 0x4d8f37 })
  for (let i = 0; i < 10; i++) {
    const h = 0.8 + random() * 2.2
    addBox(group, 0.07, h, 0.07, vineMat,
      (random() > 0.5 ? 1 : -1) * (width / 2 - 0.2),
      -0.7 - random() * 1.8,
      (random() - 0.5) * depth * 0.7, false, false)
  }

  // Grass tufts.
  for (let i = 0; i < 20; i++) {
    const x = (random() * 2 - 1) * (width / 2 - 0.5)
    const z = (random() * 2 - 1) * (depth / 2 - 0.5)
    if (Math.abs(x) < 1.4 && Math.abs(z) < 2.5) continue
    addBox(group, 0.05, 0.25 + random() * 0.25, 0.05,
      new THREE.MeshLambertMaterial({ color: random() > 0.5 ? 0x7ac84f : 0x5da63c }),
      x, 0.12, z, false, false)
  }

  if (flowers) addFlowers(group, M, random, 16, width / 2 - 0.7, depth / 2 - 0.7)

  return group
}

export function createScene() {
  const renderer = new THREE.WebGLRenderer({
    canvas: document.getElementById('scene'),
    antialias: true,
    alpha: true,
    powerPreference: 'high-performance'
  })
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2))
  renderer.outputColorSpace = THREE.SRGBColorSpace
  renderer.toneMapping = THREE.NoToneMapping
  renderer.shadowMap.enabled = true
  renderer.shadowMap.type = THREE.PCFSoftShadowMap

  configureTextures(renderer)
  const M = createMaterials()

  const scene = new THREE.Scene()
  scene.fog = new THREE.Fog(0xc7e8f4, 58, 140)

  const camera = new THREE.PerspectiveCamera(34, 1, 0.1, 240)

  const hemi = new THREE.HemisphereLight(0xdff4ff, 0x596e46, 1.45)
  scene.add(hemi)
  const sunLight = new THREE.DirectionalLight(0xfff1d2, 2.55)
  sunLight.position.set(-15, 27, 17)
  sunLight.target.position.set(2, 4, 0)
  sunLight.castShadow = true
  sunLight.shadow.mapSize.set(2048, 2048)
  sunLight.shadow.camera.left = -20
  sunLight.shadow.camera.right = 20
  sunLight.shadow.camera.top = 22
  sunLight.shadow.camera.bottom = -8
  sunLight.shadow.camera.near = 1
  sunLight.shadow.camera.far = 85
  sunLight.shadow.bias = -0.0004
  sunLight.shadow.normalBias = 0.025
  scene.add(sunLight)
  scene.add(sunLight.target)
  scene.add(new THREE.AmbientLight(0xa8c6d8, 0.28))

  const boardZone = new THREE.Group()
  const boardGroup = new THREE.Group()
  boardZone.add(boardGroup)
  scene.add(boardZone)

  const houseZone = new THREE.Group()
  const houseGroup = new THREE.Group()
  houseGroup.position.y = 0.04
  houseZone.add(houseGroup)
  scene.add(houseZone)

  /* ------------------------------ board ------------------------------ */

  const boardIsland = createIsland({ width: 12.4, depth: 9.4, seed: 3, flowers: true, M })
  boardZone.add(boardIsland)

  const w = COLS * CELL
  const h = ROWS * CELL
  const baseY = BASE_Y
  const centerY = baseY + h / 2

  // Pedestal + steps.
  addBox(boardGroup, 8.8, 0.86, 3.2, tiled(M.env.stone, 3, 1), 0, 0.43, 0)
  addBox(boardGroup, 5.4, 0.28, 1.1, tiled(M.env.stone, 2, 1), 0, 0.14, 2.0)
  addBox(boardGroup, 3.2, 0.2, 1.0, tiled(M.env.stone, 1, 1), 0, 0.1, 2.55)

  // Holographic grid backdrop.
  const gridMat = M.boardGrid.clone()
  gridMat.map = M.boardGrid.map.clone()
  gridMat.map.wrapS = gridMat.map.wrapT = THREE.RepeatWrapping
  gridMat.map.repeat.set(COLS, ROWS)
  gridMat.map.needsUpdate = true
  const back = new THREE.Mesh(new THREE.PlaneGeometry(w + 0.08, h + 0.08), gridMat)
  back.position.set(0, centerY, -0.46)
  boardGroup.add(back)

  // Wooden frame.
  const frameMat = M.env.log
  const trimMat = tiled(M.env.darkPlanks, 2, 2)
  addBox(boardGroup, 0.34, h + 0.8, 1.02, frameMat, -(w / 2 + 0.18), centerY, 0.05)
  addBox(boardGroup, 0.34, h + 0.8, 1.02, frameMat, w / 2 + 0.18, centerY, 0.05)
  addBox(boardGroup, w + 0.72, 0.34, 1.02, frameMat, 0, baseY + h + 0.34, 0.05)
  addBox(boardGroup, w + 0.72, 0.34, 1.02, frameMat, 0, baseY - 0.18, 0.05)
  addBox(boardGroup, 0.16, h + 0.5, 0.16, trimMat, -(w / 2 + 0.18), centerY, 0.45)
  addBox(boardGroup, 0.16, h + 0.5, 0.16, trimMat, w / 2 + 0.18, centerY, 0.45)
  addBox(boardGroup, 0.22, 0.22, 0.22, M.env.lantern, -(w / 2 + 0.18), baseY + h + 0.62, 0.12, false, false)
  addBox(boardGroup, 0.22, 0.22, 0.22, M.env.lantern, w / 2 + 0.18, baseY + h + 0.62, 0.12, false, false)

  // A little build sign on the pedestal.
  const boardSign = new THREE.Group()
  boardSign.position.set(-4.2, 0.2, 1.5)
  boardSign.rotation.y = 0.25
  addBox(boardSign, 0.13, 1.1, 0.13, M.env.log, 0, 0.55, 0)
  const plate = new THREE.Mesh(new THREE.PlaneGeometry(1.4, 0.55), makeSign(M))
  plate.position.set(0, 1.0, 0.08)
  boardSign.add(plate)
  boardZone.add(boardSign)

  /* ------------------------------ house ------------------------------ */

  const houseIsland = createIsland({ width: 13, depth: 11, seed: 8, flowers: true, M })
  houseZone.add(houseIsland)

  // Stepping-stone path from the porch.
  const pathMat = M.env.path
  for (let i = 0; i < 5; i++) {
    const s = 0.68 - i * 0.035
    addBox(houseZone, s, 0.07, 0.5, pathMat, (i % 2 ? 0.12 : -0.1), 0.035, 2.9 + i * 0.62, false, true)
  }

  addTree(houseZone, M, -5.0, -3.4, 1.02, 21)
  addTree(houseZone, M, 4.9, -4.0, 0.78, 33)

  const sign = new THREE.Group()
  sign.position.set(2.6, 0.03, 4.3)
  sign.rotation.y = -0.34
  addBox(sign, 0.12, 1.0, 0.12, M.env.log, 0, 0.5, 0)
  const homePlate = new THREE.Mesh(new THREE.PlaneGeometry(1.25, 0.62), makeSign(M))
  homePlate.position.set(0, 0.9, 0.07)
  sign.add(homePlate)
  houseZone.add(sign)

  // Tiny fence by the path.
  for (const x of [-1.7, 1.7]) {
    addBox(houseZone, 0.12, 0.8, 0.12, M.env.log, x, 0.4, 4.6)
    addBox(houseZone, 0.12, 0.8, 0.12, M.env.log, x, 0.4, 5.3)
    addBox(houseZone, 0.1, 0.1, 0.8, M.env.planks, x, 0.58, 4.95)
    addBox(houseZone, 0.1, 0.1, 0.8, M.env.planks, x, 0.3, 4.95)
  }

  /* ------------------------------- sky ------------------------------- */

  const cloudTex = makePuffTexture()
  const clouds = []
  const cloudRandom = rand(91)
  for (let i = 0; i < 9; i++) {
    const cloud = new THREE.Group()
    cloud.position.set(-28 + cloudRandom() * 56, 12 + cloudRandom() * 12, -24 - cloudRandom() * 32)
    cloud.scale.setScalar(0.8 + cloudRandom() * 1.2)
    const puffs = 4 + ((cloudRandom() * 4) | 0)
    for (let p = 0; p < puffs; p++) {
      const mat = new THREE.SpriteMaterial({
        map: cloudTex,
        transparent: true,
        opacity: 0.55 + cloudRandom() * 0.25,
        depthWrite: false,
        color: 0xffffff
      })
      const sprite = new THREE.Sprite(mat)
      sprite.position.set((cloudRandom() - 0.5) * 7, (cloudRandom() - 0.5) * 1.8, (cloudRandom() - 0.5) * 3)
      sprite.scale.set(4 + cloudRandom() * 5, 1.8 + cloudRandom() * 2.2, 1)
      cloud.add(sprite)
    }
    cloud.userData.speed = 0.18 + cloudRandom() * 0.22
    clouds.push(cloud)
    scene.add(cloud)
  }

  const sunTex = (() => {
    const c = document.createElement('canvas')
    c.width = c.height = 128
    const ctx = c.getContext('2d')
    const g = ctx.createRadialGradient(64, 64, 2, 64, 64, 62)
    g.addColorStop(0, 'rgba(255,253,235,1)')
    g.addColorStop(0.16, 'rgba(255,244,190,.95)')
    g.addColorStop(0.42, 'rgba(255,226,150,.38)')
    g.addColorStop(1, 'rgba(255,220,140,0)')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, 128, 128)
    const tex = new THREE.CanvasTexture(c)
    tex.colorSpace = THREE.SRGBColorSpace
    return tex
  })()
  const sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: sunTex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.95
  }))
  sunSprite.position.set(26, 25, -54)
  sunSprite.scale.set(25, 25, 1)
  scene.add(sunSprite)

  // Far-away islands for a sense of scale.
  for (const [x, y, z, s] of [[-25, 10, -40, 1.15], [28, 15, -55, 0.9], [4, 19, -68, 1.35]]) {
    const far = createIsland({ width: 7, depth: 5, seed: x + 40, flowers: false, M })
    far.position.set(x, y, z)
    far.scale.setScalar(s)
    scene.add(far)
  }

  const dustTex = makePuffTexture()
  const dustCount = 110
  const dustGeo = new THREE.BufferGeometry()
  const dustPos = new Float32Array(dustCount * 3)
  const dustSeed = rand(177)
  const dustData = []
  for (let i = 0; i < dustCount; i++) {
    const x = -22 + dustSeed() * 44
    const y = 0.5 + dustSeed() * 20
    const z = -18 + dustSeed() * 30
    dustPos[i * 3] = x
    dustPos[i * 3 + 1] = y
    dustPos[i * 3 + 2] = z
    dustData.push({ y, speed: 0.06 + dustSeed() * 0.14, drift: dustSeed() * Math.PI * 2 })
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3))
  const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
    map: dustTex, color: 0xfff2c1, size: 0.11, transparent: true, opacity: 0.55,
    depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
  }))
  scene.add(dust)

  /* ----------------------------- layout ----------------------------- */

  let mobileLayout = null

  function applyLayout(mobile) {
    mobileLayout = mobile
    if (mobile) {
      boardZone.position.set(-0.4, 0, 1.3)
      houseZone.position.set(1.8, 13.2, -4.2)
      houseZone.scale.setScalar(0.9)
      sunLight.shadow.mapSize.set(1024, 1024)
      return {
        target: new THREE.Vector3(1.0, 8.3, 0),
        dist: 28.5,
        fov: 54,
        yaw: 0.32,
        pitch: 0.25
      }
    }
    boardZone.position.set(-3.0, 0, 0.6)
    houseZone.position.set(7.3, 3.7, -1.6)
    houseZone.scale.setScalar(1)
    sunLight.shadow.mapSize.set(2048, 2048)
    return {
      target: new THREE.Vector3(2.0, 5.8, 0),
      dist: 27.5,
      fov: 34,
      yaw: 0.55,
      pitch: 0.31
    }
  }

  function updateAmbient(dt, elapsed) {
    for (const cloud of clouds) {
      cloud.position.x += cloud.userData.speed * dt
      if (cloud.position.x > 34) cloud.position.x = -34
      cloud.position.y += Math.sin(elapsed * 0.35 + cloud.position.z) * 0.0018
    }
    const pos = dustGeo.attributes.position.array
    for (let i = 0; i < dustCount; i++) {
      const d = dustData[i]
      pos[i * 3 + 1] += d.speed * dt
      pos[i * 3] += Math.sin(elapsed * 0.35 + d.drift) * 0.006
      if (pos[i * 3 + 1] > 22) pos[i * 3 + 1] = 0.3
    }
    dustGeo.attributes.position.needsUpdate = true
    sunSprite.material.opacity = 0.88 + Math.sin(elapsed * 0.5) * 0.06
  }

  function resize(width, height) {
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2))
    renderer.setSize(width, height, false)
    camera.aspect = width / height
    camera.updateProjectionMatrix()
  }

  return {
    renderer, scene, camera, M,
    boardZone, boardGroup, houseZone, houseGroup,
    applyLayout, updateAmbient, resize,
    isMobile: () => mobileLayout,
    BOARD: { width: w, height: h, baseY, centerY, cell: CELL }
  }
}

import * as THREE from '../vendor/three.module.js'
import { createHouseVoxels, HOUSE_VOXEL } from './house.js'

const boxGeo = new THREE.BoxGeometry(1, 1, 1)
const zero = new THREE.Matrix4().makeScale(0, 0, 0)

function easeOutCubic(t) {
  return 1 - Math.pow(1 - t, 3)
}
function easeOutBack(t) {
  const c1 = 1.70158
  const c3 = c1 + 1
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2)
}

export function createHouseVisual(houseGroup, M) {
  const voxels = createHouseVoxels()
  const total = voxels.length
  const dummy = new THREE.Object3D()
  const V = HOUSE_VOXEL
  const SCALE = V * 0.97

  const byMaterial = new Map()
  for (const voxel of voxels) {
    if (!byMaterial.has(voxel.mat)) byMaterial.set(voxel.mat, [])
    byMaterial.get(voxel.mat).push(voxel)
  }

  const solidMeshes = []
  for (const [mat, list] of byMaterial) {
    const material = M.house[mat]
    const mesh = new THREE.InstancedMesh(boxGeo, material, list.length)
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    mesh.castShadow = mat !== 'glass' && mat !== 'lantern'
    mesh.receiveShadow = true
    mesh.frustumCulled = false
    houseGroup.add(mesh)
    solidMeshes.push(mesh)
    list.forEach((voxel, index) => {
      voxel.solid = { mesh, index }
      mesh.setMatrixAt(index, zero)
    })
    mesh.instanceMatrix.needsUpdate = true
  }

  const ghost = new THREE.InstancedMesh(boxGeo, M.ghost, total)
  ghost.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
  ghost.frustumCulled = false
  ghost.renderOrder = 2
  ghost.castShadow = false
  ghost.receiveShadow = false
  ghost.visible = true
  houseGroup.add(ghost)

  let builtCount = 0
  const animating = []

  function setMatrix(voxel, scale, yOffset = 0) {
    if (scale <= 0.001) {
      voxel.solid.mesh.setMatrixAt(voxel.solid.index, zero)
      return
    }
    dummy.position.set(voxel.x * V, (voxel.y + 0.5) * V + yOffset, voxel.z * V)
    dummy.rotation.set(0, 0, 0)
    dummy.scale.setScalar(SCALE * scale)
    dummy.updateMatrix()
    voxel.solid.mesh.setMatrixAt(voxel.solid.index, dummy.matrix)
  }

  function setGhost(voxel, visible) {
    if (!visible) {
      ghost.setMatrixAt(voxel.ghostIndex, zero)
      return
    }
    dummy.position.set(voxel.x * V, (voxel.y + 0.5) * V, voxel.z * V)
    dummy.rotation.set(0, 0, 0)
    dummy.scale.setScalar(V * 0.94)
    dummy.updateMatrix()
    ghost.setMatrixAt(voxel.ghostIndex, dummy.matrix)
  }

  voxels.forEach((voxel, index) => {
    voxel.ghostIndex = index
    voxel.built = false
    setGhost(voxel, true)
  })
  ghost.instanceMatrix.needsUpdate = true

  function build(voxel, immediate = false) {
    if (!voxel || voxel.built) return false
    voxel.built = true
    builtCount++
    setGhost(voxel, false)
    ghost.instanceMatrix.needsUpdate = true
    if (immediate) {
      setMatrix(voxel, 1)
      voxel.solid.mesh.instanceMatrix.needsUpdate = true
    } else {
      voxel.anim = 0
      voxel.animDelay = 0
      animating.push(voxel)
    }
    return true
  }

  function buildAll(immediate = true) {
    for (const voxel of voxels) build(voxel, immediate)
    if (immediate) ghost.visible = false
  }

  function reset() {
    builtCount = 0
    animating.length = 0
    ghost.visible = true
    for (const voxel of voxels) {
      voxel.built = false
      voxel.anim = 0
      setMatrix(voxel, 0)
      setGhost(voxel, true)
    }
    for (const mesh of solidMeshes) mesh.instanceMatrix.needsUpdate = true
    ghost.instanceMatrix.needsUpdate = true
  }

  function update(dt) {
    if (!animating.length) return
    for (let i = animating.length - 1; i >= 0; i--) {
      const voxel = animating[i]
      if (voxel.animDelay > 0) {
        voxel.animDelay -= dt
        setMatrix(voxel, 0.001, 0.15)
        voxel.solid.mesh.instanceMatrix.needsUpdate = true
        continue
      }
      voxel.anim += dt / 0.38
      const t = Math.min(1, voxel.anim)
      const scale = Math.max(0.001, easeOutBack(t))
      const yOffset = (1 - easeOutCubic(t)) * 0.62
      setMatrix(voxel, scale, yOffset)
      voxel.solid.mesh.instanceMatrix.needsUpdate = true
      if (t >= 1) {
        setMatrix(voxel, 1, 0)
        voxel.solid.mesh.instanceMatrix.needsUpdate = true
        animating.splice(i, 1)
      }
    }
  }

  function worldPosition(voxel, target = new THREE.Vector3()) {
    houseGroup.updateWorldMatrix(true, false)
    return target
      .set(voxel.x * V, (voxel.y + 0.5) * V, voxel.z * V)
      .applyMatrix4(houseGroup.matrixWorld)
  }

  function center(target = new THREE.Vector3()) {
    houseGroup.updateWorldMatrix(true, false)
    return target.set(0, 3.0, 0).applyMatrix4(houseGroup.matrixWorld)
  }

  return {
    voxels,
    total,
    ghost,
    solidMeshes,
    build,
    buildAll,
    reset,
    update,
    worldPosition,
    center,
    get builtCount() { return builtCount },
    get percent() { return total ? builtCount / total : 0 }
  }
}

import * as THREE from '../vendor/three.module.js'
import { COLS } from './tetris.js'
import { CELL, BASE_Y } from './scene.js'

const boxGeo = new THREE.BoxGeometry(1, 1, 1)
const flashGeo = new THREE.PlaneGeometry(1, 1)

export function createBoardVisual(boardGroup, M) {
  const lockedLayer = new THREE.Group()
  const pieceLayer = new THREE.Group()
  const ghostLayer = new THREE.Group()
  ghostLayer.renderOrder = 2
  boardGroup.add(lockedLayer)
  boardGroup.add(pieceLayer)
  boardGroup.add(ghostLayer)

  const ghostMats = {}
  for (const type of Object.keys(M.piece)) {
    ghostMats[type] = new THREE.MeshBasicMaterial({
      map: M.piece[type].map,
      transparent: true,
      opacity: 0.3,
      depthWrite: false,
      toneMapped: false
    })
  }

  let pieceGroup = null
  let ghostGroup = null
  let ghostSignature = ''
  let pulse = 0
  let lastType = null
  const flashes = []

  function renderCells(board) {
    while (lockedLayer.children.length) {
      lockedLayer.remove(lockedLayer.children[0])
    }
    for (let row = 0; row < board.length; row++) {
      for (let col = 0; col < COLS; col++) {
        const type = board[row][col]
        if (!type) continue
        const mesh = new THREE.Mesh(boxGeo, M.piece[type])
        mesh.scale.setScalar(CELL * 0.96)
        mesh.position.set(
          (col - (COLS - 1) / 2) * CELL,
          BASE_Y + row * CELL + CELL / 2,
          0
        )
        mesh.castShadow = true
        mesh.receiveShadow = true
        lockedLayer.add(mesh)
      }
    }
  }

  function shapeChildPositions(group, cells) {
    const children = group.children
    for (let i = 0; i < cells.length; i++) {
      if (!children[i]) continue
      children[i].position.set(cells[i][0] * CELL, cells[i][1] * CELL + CELL / 2, 0)
    }
  }

  function createPiece(active) {
    removePiece()
    lastType = active.type
    pieceGroup = new THREE.Group()
    for (let i = 0; i < 4; i++) {
      const mesh = new THREE.Mesh(boxGeo, M.piece[active.type])
      mesh.scale.setScalar(CELL * 0.96)
      mesh.castShadow = true
      mesh.receiveShadow = true
      pieceGroup.add(mesh)
    }
    shapeChildPositions(pieceGroup, active.cells)
    pieceGroup.position.set(
      (active.x - (COLS - 1) / 2) * CELL,
      BASE_Y + active.y * CELL,
      0
    )
    pieceLayer.add(pieceGroup)
    pulse = 0.9
    createGhost(active)
  }

  function removePiece() {
    if (!pieceGroup) return
    pieceLayer.remove(pieceGroup)
    pieceGroup = null
    lastType = null
  }

  function updatePiece(active, dt, snap = false) {
    if (!pieceGroup || !active) return
    const tx = (active.x - (COLS - 1) / 2) * CELL
    const ty = BASE_Y + active.y * CELL
    if (snap) {
      pieceGroup.position.x = tx
      pieceGroup.position.y = ty
    } else {
      const lambda = 26
      pieceGroup.position.x = THREE.MathUtils.damp(pieceGroup.position.x, tx, lambda, dt)
      pieceGroup.position.y = THREE.MathUtils.damp(pieceGroup.position.y, ty, lambda, dt)
    }
    shapeChildPositions(pieceGroup, active.cells)
    pulse = Math.max(0, pulse - dt * 7)
    const s = 1 + Math.sin(pulse * Math.PI) * 0.07
    pieceGroup.scale.setScalar(s)
    showGhost(active)
  }

  function createGhost(active) {
    removeGhost()
    ghostGroup = new THREE.Group()
    ghostSignature = `${active.type}:${active.rot}`
    for (let i = 0; i < 4; i++) {
      const mesh = new THREE.Mesh(boxGeo, ghostMats[active.type])
      mesh.scale.setScalar(CELL * 0.92)
      ghostGroup.add(mesh)
    }
    shapeChildPositions(ghostGroup, active.cells)
    ghostLayer.add(ghostGroup)
  }

  function removeGhost() {
    if (!ghostGroup) return
    ghostLayer.remove(ghostGroup)
    ghostGroup = null
    ghostSignature = ''
  }

  function showGhost(active) {
    if (!active) {
      if (ghostGroup) ghostGroup.visible = false
      return
    }
    if (!ghostGroup) createGhost(active)
    const sig = `${active.type}:${active.rot}`
    if (sig !== ghostSignature) {
      ghostSignature = sig
      shapeChildPositions(ghostGroup, active.cells)
    }
    ghostGroup.visible = true
    let ly = active.y
    // The ghost drops until the piece would hit anything.
    const probe = active.cells
    while (true) {
      let blocked = false
      for (const [cx, cy] of probe) {
        const bx = active.x + cx
        const by = ly - 1 + cy
        if (by < 0) { blocked = true; break }
        if (by < boardHeight()) {
          // board is supplied through closure below; guarded by caller
        }
      }
      if (blocked) break
      if (!canDrop(active, ly - 1)) break
      ly--
    }
    ghostGroup.position.set(
      (active.x - (COLS - 1) / 2) * CELL,
      BASE_Y + ly * CELL,
      0
    )
  }

  // Updated by main so the ghost can query the live board.
  let liveBoard = []
  let boardHeight = () => liveBoard.length
  let canDrop = (active, y) => {
    for (const [cx, cy] of active.cells) {
      const bx = active.x + cx
      const by = y + cy
      if (by < 0) return false
      if (by < liveBoard.length && liveBoard[by] && liveBoard[by][bx]) return false
    }
    return true
  }

  function setBoard(board) {
    liveBoard = board
  }

  function worldCell(row, col, target = new THREE.Vector3()) {
    return target
      .set((col - (COLS - 1) / 2) * CELL, BASE_Y + row * CELL + CELL / 2, 0)
      .applyMatrix4(boardGroup.matrixWorld)
  }

  function flashRows(rows) {
    for (const row of rows) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.75,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false
      })
      const mesh = new THREE.Mesh(flashGeo, mat)
      mesh.scale.set(COLS * CELL * 1.03, CELL * 0.98, 1)
      mesh.position.set(0, BASE_Y + row * CELL + CELL / 2, 0.52)
      boardGroup.add(mesh)
      flashes.push({ mesh, life: 0.35, max: 0.35 })
    }
  }

  function update(dt) {
    for (let i = flashes.length - 1; i >= 0; i--) {
      const f = flashes[i]
      f.life -= dt
      const t = Math.max(0, f.life / f.max)
      f.mesh.material.opacity = t * 0.8
      f.mesh.scale.x = COLS * CELL * (1.03 + (1 - t) * 0.16)
      if (f.life <= 0) {
        boardGroup.remove(f.mesh)
        f.mesh.material.dispose()
        flashes.splice(i, 1)
      }
    }
  }

  function reset() {
    removePiece()
    removeGhost()
    while (lockedLayer.children.length) lockedLayer.remove(lockedLayer.children[0])
    for (const f of flashes) {
      boardGroup.remove(f.mesh)
      f.mesh.material.dispose()
    }
    flashes.length = 0
    pulse = 0
  }

  return {
    renderCells,
    createPiece,
    removePiece,
    updatePiece,
    showGhost,
    removeGhost,
    setBoard,
    worldCell,
    flashRows,
    update,
    reset,
    get ghostGroup() { return ghostGroup }
  }
}

import * as THREE from '../vendor/three.module.js'
import { PIECE_COLORS } from './textures.js'

const boxGeo = new THREE.BoxGeometry(1, 1, 1)
const dummy = new THREE.Object3D()
const tmpColor = new THREE.Color()

export function createEffects(scene) {
  const MAX = 260
  const material = new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false })
  const mesh = new THREE.InstancedMesh(boxGeo, material, MAX)
  mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
  mesh.frustumCulled = false
  mesh.castShadow = false
  mesh.receiveShadow = false
  for (let i = 0; i < MAX; i++) mesh.setColorAt(i, tmpColor.set(0xffffff))
  mesh.instanceColor.needsUpdate = true
  scene.add(mesh)

  const pool = []
  for (let i = 0; i < MAX; i++) {
    pool.push({
      active: false,
      pos: new THREE.Vector3(),
      vel: new THREE.Vector3(),
      life: 0,
      maxLife: 1,
      size: 0.1,
      gravity: 8,
      spin: 0,
      rot: new THREE.Euler()
    })
    mesh.setMatrixAt(i, new THREE.Matrix4().makeScale(0, 0, 0))
  }
  mesh.instanceMatrix.needsUpdate = true
  let cursor = 0

  function spawn(position, colorHex, options = {}) {
    const {
      count = 8, speed = 2.2, size = 0.09, gravity = 7,
      life = 0.55, spread = 1, up = 1.8
    } = options
    for (let n = 0; n < count; n++) {
      const i = cursor
      cursor = (cursor + 1) % MAX
      const p = pool[i]
      p.active = true
      p.pos.copy(position)
      p.pos.x += (Math.random() - 0.5) * spread
      p.pos.y += (Math.random() - 0.5) * spread * 0.6
      p.pos.z += (Math.random() - 0.5) * spread
      p.vel.set(
        (Math.random() - 0.5) * speed,
        Math.random() * speed * 0.75 + up,
        (Math.random() - 0.5) * speed
      )
      p.life = p.maxLife = life * (0.7 + Math.random() * 0.6)
      p.size = size * (0.65 + Math.random() * 0.8)
      p.gravity = gravity
      p.spin = (Math.random() - 0.5) * 10
      p.rot.set(Math.random() * 6, Math.random() * 6, Math.random() * 6)
      mesh.setColorAt(i, tmpColor.set(colorHex))
    }
    mesh.instanceColor.needsUpdate = true
  }

  function confetti(center, count = 120) {
    const colors = ['#ef6a5a', '#f2c94c', '#67c75f', '#54d9e8', '#b46fe4', '#ff9f68', '#fff2c1']
    for (let n = 0; n < count; n++) {
      const i = cursor
      cursor = (cursor + 1) % MAX
      const p = pool[i]
      p.active = true
      p.pos.copy(center)
      p.pos.x += (Math.random() - 0.5) * 7
      p.pos.y += Math.random() * 3
      p.pos.z += (Math.random() - 0.5) * 5
      p.vel.set((Math.random() - 0.5) * 3.2, 2 + Math.random() * 3.6, (Math.random() - 0.5) * 3.2)
      p.life = p.maxLife = 1.7 + Math.random() * 1.1
      p.size = 0.09 + Math.random() * 0.09
      p.gravity = 4.2
      p.spin = (Math.random() - 0.5) * 14
      p.rot.set(Math.random() * 6, Math.random() * 6, Math.random() * 6)
      mesh.setColorAt(i, tmpColor.set(colors[(Math.random() * colors.length) | 0]))
    }
    mesh.instanceColor.needsUpdate = true
  }

  function update(dt) {
    let dirty = false
    for (let i = 0; i < MAX; i++) {
      const p = pool[i]
      if (!p.active) continue
      dirty = true
      p.life -= dt
      if (p.life <= 0) {
        p.active = false
        mesh.setMatrixAt(i, new THREE.Matrix4().makeScale(0, 0, 0))
        continue
      }
      p.vel.y -= p.gravity * dt
      p.pos.addScaledVector(p.vel, dt)
      p.rot.x += p.spin * dt
      p.rot.y += p.spin * 0.7 * dt
      const t = Math.max(0, p.life / p.maxLife)
      const scale = p.size * (0.3 + t * 0.7)
      dummy.position.copy(p.pos)
      dummy.rotation.copy(p.rot)
      dummy.scale.setScalar(scale)
      dummy.updateMatrix()
      mesh.setMatrixAt(i, dummy.matrix)
    }
    if (dirty) mesh.instanceMatrix.needsUpdate = true
  }

  function clear() {
    for (let i = 0; i < MAX; i++) {
      pool[i].active = false
      mesh.setMatrixAt(i, new THREE.Matrix4().makeScale(0, 0, 0))
    }
    mesh.instanceMatrix.needsUpdate = true
  }

  return { spawn, confetti, update, clear }
}

export function createFlights(scene, M, onLand) {
  const flights = []

  function launch(start, end, type, targets, options = {}) {
    const material = M.piece[type] || M.piece.O
    const cube = new THREE.Mesh(boxGeo, material)
    cube.scale.setScalar(options.size || 0.22)
    cube.position.copy(start)
    cube.castShadow = false
    scene.add(cube)
    const mid = start.clone().add(end).multiplyScalar(0.5)
    mid.y += options.arc || (3.5 + Math.random() * 4)
    mid.x += (Math.random() - 0.5) * 2.4
    mid.z += (Math.random() - 0.5) * 1.6
    const dist = start.distanceTo(end)
    flights.push({
      cube,
      start: start.clone(),
      control: mid,
      end: end.clone(),
      t: 0,
      duration: options.duration || 0.62 + dist * 0.012,
      targets: targets || [],
      spin: new THREE.Vector3(
        (Math.random() - 0.5) * 6,
        (Math.random() - 0.5) * 6,
        (Math.random() - 0.5) * 6
      )
    })
  }

  function update(dt) {
    for (let i = flights.length - 1; i >= 0; i--) {
      const f = flights[i]
      f.t += dt / f.duration
      const t = Math.min(1, f.t)
      const e = t * t * (3 - 2 * t)
      // Quadratic Bézier.
      const a = (1 - e) * (1 - e)
      const b = 2 * (1 - e) * e
      const c = e * e
      f.cube.position.set(
        a * f.start.x + b * f.control.x + c * f.end.x,
        a * f.start.y + b * f.control.y + c * f.end.y,
        a * f.start.z + b * f.control.z + c * f.end.z
      )
      f.cube.rotation.x += f.spin.x * dt
      f.cube.rotation.y += f.spin.y * dt
      f.cube.rotation.z += f.spin.z * dt
      f.cube.scale.setScalar((0.22 + Math.sin(t * Math.PI) * 0.05) * (1 - (t > 0.86 ? (t - 0.86) / 0.14 * 0.6 : 0)))
      if (t >= 1) {
        scene.remove(f.cube)
        if (f.targets.length) onLand(f.targets, f.end)
        flights.splice(i, 1)
      }
    }
  }

  function clear() {
    for (const f of flights) scene.remove(f.cube)
    flights.length = 0
  }

  return { launch, update, clear, get count() { return flights.length } }
}

export class GameAudio {
  constructor() {
    this.ctx = null
    this.master = null
    this.enabled = true
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.enabled ? 0.16 : 0
    this.master.connect(this.ctx.destination)
  }

  setEnabled(enabled) {
    this.enabled = enabled
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(enabled ? 0.16 : 0, this.ctx.currentTime, 0.02)
    }
  }

  tone(freq, duration = 0.08, type = 'square', volume = 0.5, slide = 1, delay = 0) {
    if (!this.enabled || !this.ctx || !this.master) return
    const t = this.ctx.currentTime + delay
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    if (slide !== 1) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq * slide), t + duration)
    gain.gain.setValueAtTime(0.0001, t)
    gain.gain.exponentialRampToValueAtTime(volume, t + 0.008)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    osc.connect(gain)
    gain.connect(this.master)
    osc.start(t)
    osc.stop(t + duration + 0.02)
  }

  noise(duration = 0.1, volume = 0.4, cutoff = 900, delay = 0) {
    if (!this.enabled || !this.ctx || !this.master) return
    const t = this.ctx.currentTime + delay
    const length = Math.max(1, (this.ctx.sampleRate * duration) | 0)
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / length)
    const source = this.ctx.createBufferSource()
    source.buffer = buffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = cutoff
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(volume, t)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    source.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    source.start(t)
  }

  move() { this.tone(240, 0.035, 'square', 0.16) }
  rotate() { this.tone(390, 0.045, 'square', 0.2) }
  hold() { this.tone(520, 0.07, 'triangle', 0.25, 1.4) }
  lock() {
    this.noise(0.08, 0.35, 700)
    this.tone(90, 0.09, 'sine', 0.5, 0.7)
  }
  hardDrop() {
    this.noise(0.13, 0.5, 500)
    this.tone(70, 0.14, 'sine', 0.6, 0.6)
  }
  clear(count = 1) {
    const notes = [523.25, 659.25, 783.99, 1046.5]
    for (let i = 0; i < Math.min(4, count + 1); i++) {
      this.tone(notes[i], 0.13, 'triangle', 0.34, 1, i * 0.065)
    }
  }
  build() {
    this.tone(880 + Math.random() * 110, 0.06, 'triangle', 0.16, 1.03)
  }
  start() {
    const notes = [392, 523.25, 659.25, 783.99]
    notes.forEach((n, i) => this.tone(n, 0.16, 'triangle', 0.32, 1.02, i * 0.085))
  }
  win() {
    const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5, 1046.5, 1318.5, 1568]
    notes.forEach((n, i) => {
      this.tone(n, 0.24, 'triangle', 0.33, 1.02, i * 0.11)
      this.tone(n / 2, 0.24, 'sine', 0.16, 1.02, i * 0.11)
    })
  }
  lose() {
    const notes = [392, 349.23, 293.66, 246.94, 196]
    notes.forEach((n, i) => this.tone(n, 0.2, 'sawtooth', 0.2, 0.96, i * 0.12))
  }
}

