let lastFrame = performance.now()
function frame(now) {
  const dt = Math.min(0.05, Math.max(0, (now - lastFrame) / 1000))
  lastFrame = now
  elapsed += dt

  stage.updateAmbient(dt, elapsed)
  updateVisuals(dt)
  effects.update(dt)
  flights.update(dt)
  updateGame(dt)
  rig.update(dt)
  updateScoreDisplay(dt)

  renderer.render(scene, camera)
  requestAnimationFrame(frame)
}

